import{_ as e,c as a,o as i,ae as o}from"./chunks/framework.CliRSA9F.js";const r="/images/platform_editorial.webp",m=JSON.parse('{"title":"Curated Lists","description":"","frontmatter":{},"headers":[],"relativePath":"features/curated-lists.md","filePath":"features/curated-lists.md"}'),s={name:"features/curated-lists.md"};function l(n,t,d,c,p,u){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="curated-lists" tabindex="-1">Curated Lists <a class="header-anchor" href="#curated-lists" aria-label="Permalink to &quot;Curated Lists&quot;">​</a></h1><h2 id="browse-platform-curated-podcast-collections" tabindex="-1">Browse Platform-Curated Podcast Collections <a class="header-anchor" href="#browse-platform-curated-podcast-collections" aria-label="Permalink to &quot;Browse Platform-Curated Podcast Collections&quot;">​</a></h2><p>Curated Lists lets you explore curated podcast collections from major platforms. Browse editorial features from Apple Podcasts, Spotify, Amazon Music, and YouTube Music to understand what platforms are promoting and discover strategic opportunities.</p><p><img src="'+r+'" alt="Curated Lists" width="600px" style="display:block;margin:0 auto;"></p><h2 id="what-are-editorial-lists" tabindex="-1">What Are Editorial Lists? <a class="header-anchor" href="#what-are-editorial-lists" aria-label="Permalink to &quot;What Are Editorial Lists?&quot;">​</a></h2><p>Podcast platforms maintain editorial teams that curate collections of recommended podcasts. These collections appear in prominent positions within each platform&#39;s app, driving significant discovery for featured podcasts. Examples include:</p><ul><li>Apple Podcasts&#39; &quot;New &amp; Noteworthy&quot; and themed collections</li><li>Spotify&#39;s editorial playlists and featured podcast sections</li><li>Amazon Music&#39;s curated podcast recommendations</li><li>YouTube Music&#39;s podcast highlights</li></ul><p>PodSEO tracks these editorial features across all major platforms, giving you visibility into what&#39;s being promoted.</p><h2 id="how-to-use-curated-lists" tabindex="-1">How to Use Curated Lists <a class="header-anchor" href="#how-to-use-curated-lists" aria-label="Permalink to &quot;How to Use Curated Lists&quot;">​</a></h2><h3 id="browse-by-platform" tabindex="-1">Browse by Platform <a class="header-anchor" href="#browse-by-platform" aria-label="Permalink to &quot;Browse by Platform&quot;">​</a></h3><p>Use the platform chips at the top to choose a platform, and the editorial lists for that platform load below:</p><ul><li><strong>Apple Podcasts</strong> - Editorial collections, New &amp; Noteworthy, category features</li><li><strong>Spotify</strong> - Editorial playlists, genre features, trending selections</li><li><strong>Amazon Music</strong> - Curated collections and platform recommendations</li><li><strong>YouTube Music</strong> - Featured podcast content</li></ul><p>Switch between platforms to see what each one is currently promoting.</p><h3 id="explore-individual-lists" tabindex="-1">Explore Individual Lists <a class="header-anchor" href="#explore-individual-lists" aria-label="Permalink to &quot;Explore Individual Lists&quot;">​</a></h3><p>Each editorial list shows:</p><ul><li>The list name</li><li>The podcasts currently featured on it</li><li>The platform it belongs to</li></ul><h2 id="strategic-applications" tabindex="-1">Strategic Applications <a class="header-anchor" href="#strategic-applications" aria-label="Permalink to &quot;Strategic Applications&quot;">​</a></h2><h3 id="competitive-intelligence" tabindex="-1">Competitive Intelligence <a class="header-anchor" href="#competitive-intelligence" aria-label="Permalink to &quot;Competitive Intelligence&quot;">​</a></h3><p>Understanding editorial placement helps you:</p><ul><li>See which competitors receive editorial features</li><li>Identify patterns in what platforms choose to promote</li><li>Spot gaps where your podcast could fit</li></ul><h3 id="content-planning" tabindex="-1">Content Planning <a class="header-anchor" href="#content-planning" aria-label="Permalink to &quot;Content Planning&quot;">​</a></h3><p>Editorial lists reveal platform priorities:</p><ul><li>Seasonal themes and trending topics</li><li>Content types that receive promotion</li><li>Categories with active editorial support</li></ul><h3 id="opportunity-identification" tabindex="-1">Opportunity Identification <a class="header-anchor" href="#opportunity-identification" aria-label="Permalink to &quot;Opportunity Identification&quot;">​</a></h3><p>Use editorial research to guide your strategy:</p><ul><li>Find editorial lists relevant to your podcast&#39;s topic</li><li>Understand the quality and style of featured podcasts</li><li>Identify lists where your podcast could potentially appear</li></ul><h2 id="connection-to-my-placements" tabindex="-1">Connection to My Placements <a class="header-anchor" href="#connection-to-my-placements" aria-label="Permalink to &quot;Connection to My Placements&quot;">​</a></h2><p>Curated Lists shows the broader landscape of platform editorial content. <a href="/features/my-placements.html">My Placements</a> shows where your specific podcast has been featured.</p><p>Use both together:</p><ol><li><strong>Curated Lists</strong> - Research what&#39;s being promoted across platforms</li><li><strong>My Placements</strong> - Track your own editorial appearances</li></ol><h2 id="requesting-editorial-features" tabindex="-1">Requesting Editorial Features <a class="header-anchor" href="#requesting-editorial-features" aria-label="Permalink to &quot;Requesting Editorial Features&quot;">​</a></h2><p>While editorial placement isn&#39;t guaranteed, platforms do accept feature requests. For Apple Podcasts, use their <a href="https://airtable.com/appL7FlZuT3KbtUz0/pagX0sfhAxqSB6zp4/form" target="_blank" rel="noreferrer">official feature request form</a> and follow their <a href="https://podcasters.apple.com/support/1993-optimize-your-request-for-promotion" target="_blank" rel="noreferrer">optimization guide</a>.</p><p>Key tips for editorial consideration:</p><ul><li>Submit requests at least 2 weeks before your desired feature date</li><li>Prepare special artwork following platform templates</li><li>Have a compelling story about why your content deserves promotion</li><li>Maintain consistently high content quality</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Curated Lists is available to all users. The data updates regularly as PodSEO monitors editorial content across platforms.</p><p><strong>Related Features</strong>: Check <a href="/features/my-placements.html">My Placements</a> to see your own podcast&#39;s editorial appearances, and use <a href="/features/all-charts.html">All Charts</a> to track chart rankings alongside editorial visibility.</p>',37)])])}const f=e(s,[["render",l]]);export{m as __pageData,f as default};
